function draw() {
    // dark background
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // light effect around the player
    const gradient = ctx.createRadialGradient(
      player.x, player.y, 0,
      player.x, player.y, LIGHT_RADIUS
    );
    gradient.addColorStop(0, 'rgba(255,255,200,0.8)');
    gradient.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // draw crystals
    ctx.fillStyle = '#0ff';
    crystals.forEach(c => {
      // outer glow
      const glow = ctx.createRadialGradient(c.x, c.y, 0, c.x, c.y, c.r * 3);
      glow.addColorStop(0, 'rgba(0,255,255,0.6)');
      glow.addColorStop(1, 'rgba(0,255,255,0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(c.x, c.y, c.r * 3, 0, Math.PI * 2);
      ctx.fill();
      // core crystal
      ctx.fillStyle = '#0ff';
      ctx.beginPath();
      ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
      ctx.fill();
    });

    // draw enemies
    ctx.fillStyle = '#f44';
    enemies.forEach(e => {
      ctx.beginPath();
      ctx.arc(e.x, e.y, e.r, 0, Math.PI * 2);
      ctx.fill();
    });

    // draw player (glowing orb)
    ctx.fillStyle = '#ff0';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.r, 0, Math.PI * 2);
    ctx.fill();

    // UI – score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 20, 30);

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

